import { kebabCase, keyBy } from 'es-toolkit';
import { truncate } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function toSlug(label: string): string {
  return kebabCase(label);
}

export function byNameKey(rows: Row[]): Record<string, Row> {
  return keyBy(rows, row => row.name);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
cat > out/t.mjs <<'EOF'
import l from 'lodash/kebabCase.js';
import {kebabCase} from 'es-toolkit';
let bad=0;const cs='aAbB09 -_.xyZ';
for(let i=0;i<200000;i++){let n=Math.random()*40|0,s='';for(let j=0;j<n;j++)s+=cs[Math.random()*cs.length|0];if(l(s)!==kebabCase(s)){if(bad++<5)console.log(JSON.stringify(s),l(s),kebabCase(s));}}
console.log('bad',bad);
EOF
cp out/t.mjs ./t.mjs && node t.mjs; rm t.mjs out/t.mjs
npm run size -- out/module.ts; npm run size -- src/module.ts

